B.Hw=s(["kecepatan","laju","km/jam","arti"],t.s)
B.Rh=new A.de("Apa itu kecepatan?","Kecepatan adalah jarak yang ditempuh dalam satu satuan waktu. Contoh: 60 km/jam artinya setiap 1 jam menempuh 60 km.",B.Hw)
B.Hl=s(["rumus","jkw","segitiga","jarak","waktu","kecepatan","cara","hitung"],t.s)
B.Rj=new A.de("Apa rumus jarak, kecepatan, dan waktu?","Jarak = kecepatan \xd7 waktu.\nKecepatan = jarak \xf7 waktu.\nWaktu = jarak \xf7 kecepatan.\nIngat segitiga JKW: J di atas, K dan W di bawah. Tutup yang dicari, lihat sisanya.",B.Hl)
B.HG=s(["menit","jam","ubah","konversi","satuan","bagi","60"],t.s)
B.Rg=new A.de("Bagaimana mengubah menit ke jam?","Bagi dengan 60. Contoh: 30 menit = 30 \xf7 60 = 0,5 jam. 45 menit = 45 \xf7 60 = 0,75 jam.",B.HG)
B.Ha=s(["jam","menit","ubah","konversi","kali","60"],t.s)
B.Rk=new A.de("Bagaimana mengubah jam ke menit?","Kalikan dengan 60. Contoh: 1,5 jam = 1,5 \xd7 60 = 90 menit.",B.Ha)
B.I9=s(["satuan","sama","samakan","menit","salah","kenapa"],t.s)
B.Ro=new A.de("Kenapa satuannya harus disamakan dulu?","Kalau kecepatan dalam km/jam tetapi waktu dalam menit, hasilnya pasti salah. Contoh: 6 km dalam 30 menit. 6 \xf7 30 = 0,2 itu salah. Ubah dulu 30 menit = 0,5 jam, lalu 6 \xf7 0,5 = 12 km/jam.",B.I9)
B.HQ=s(["km","meter","m","ubah","konversi","1000"],t.s)
B.Rp=new A.de("Bagaimana mengubah km ke m?","Kalikan dengan 1.000. Contoh: 3 km = 3 \xd7 1.000 = 3.000 m. Sebaliknya, m ke km dibagi 1.000.",B.HQ)
B.Iz=s(["km/jam","m/detik","detik","ubah","konversi","3600"],t.s)
B.Rr=new A.de("Bagaimana mengubah km/jam ke m/detik?","Kalikan 1.000 (km ke m), lalu bagi 3.600 (jam ke detik). Contoh: 72 km/jam = 72 \xd7 1.000 \xf7 3.600 = 20 m/detik.",B.Iz)
B.Hz=s(["rata-rata","rata","total","andi"],t.s)
B.Rs=new A.de("Apa itu kecepatan rata-rata?","Kecepatan rata-rata = total jarak \xf7 total waktu. Bukan rata-rata dari dua kecepatan! Contoh soal Andi: 10 km \xf7 1 jam = 10 km/jam.",B.Hz)
B.J2=s(["pukul","jam","lama","berangkat","beda","waktu tempuh"],t.s)
B.Rn=new A.de("Apa bedanya jam berangkat dengan lama perjalanan?",'"Pukul 07.00" adalah jam (waktu pada jam dinding). "2 jam" atau "30 menit" adalah lama perjalanan. Yang dipakai di rumus adalah lama perjalanan.',B.J2)
B.IP=s(["waktu tempuh","tempuh","lama"],t.s)
B.Ri=new A.de("Apa itu waktu tempuh?","Waktu tempuh adalah lama perjalanan dari tempat awal sampai tujuan.",B.IP)
B.IX=s(["rute","pilih","tepat waktu","batas","dina","bandingkan"],t.s)
B.Rq=new A.de("Bagaimana cara memilih rute yang tepat waktu?","Hitung waktu tiap rute (jarak \xf7 kecepatan), ubah ke menit, lalu bandingkan dengan batas waktunya. Pilih rute yang waktunya tidak melebihi batas.",B.IX)
B.Hi=s(["cek","masuk akal","periksa","logika","benar","salah","budi"],t.s)
B.Rf=new A.de("Bagaimana tahu jawabanku masuk akal?","Cek dengan logika. Kendaraan lebih cepat \u2192 waktunya lebih singkat. Kalikan kembali: kecepatan \xd7 waktu harus sama dengan jarak. Sepeda biasanya 10\u201320 km/jam. Kalau hasilmu 0,2 km/jam atau 180 km/jam, pasti ada yang salah.",B.Hi)
B.IN=s(["15","30","45","menit","pecahan","seperempat","setengah"],t.s)
B.Rl=new A.de("Berapa jam 15, 30, dan 45 menit?","15 menit = \xbc jam = 0,25 jam.\n30 menit = \xbd jam = 0,5 jam.\n45 menit = \xbe jam = 0,75 jam.",B.IN)
B.IH=s(["kalkulator","hitung","pakai","cara"],t.s)
B.Rm=new A.de("Bagaimana cara memakai kalkulator di aplikasi ini?","Ketuk tombol \ud83e\uddee. Tulis hitunganmu, misalnya 150 \xf7 50, lalu tekan =. Pakai koma untuk desimal, misalnya 6 \xf7 0,5.",B.IH)
